\": \"279885\", \"owner\": \"postgres\", \"strict\": false, \"execute\": [\"authenticated\", \"postgres\"], \"body_md5\": \"c8e14eabaffe8a545d57bd7ea4f63ca8\", \"language\": \"plpgsql\", \"parallel\": \"u\", \"arg_modes\": [\"i\"], \"arg_names\": [\"p_session\"], \"volatility\": \"v\", \"return_type\": \"pg_catalog.jsonb\", \"returns_set\": false, \"all_arg_types\": [\"pg_catalog.uuid\"], \"configuration\": [\"search_path=\\\"\\\"\"], \"variadic_type\": null, \"input_arg_types\": [\"pg_catalog.uuid\"], \"lookup_signature\": \"public.mission_factory_quest_human_successor_scope_v1(pg_catalog.uuid)\", \"security_definer\": true, \"default_arg_count\": 0}]}, \"schema_version\": \"human-ordinary-release-tuple/1\", \"legacy_dependency\": \"37dac90525b249f53fc0404b50adb4ed92df0123649326c99260bf656119d806\"}","human_release_sha256":"5ab4234b32294cc26472855447e6230f62c5e07308768816ae0c2ea304d94366","staff_guards_verified":true,"observed_revision_sha256":"5ab4234b32294cc26472855447e6230f62c5e07308768816ae0c2ea304d94366","published_assets_verified":true,"actual_edge_binding_sha256":"cb4c7311616a5019acde06ffa9ac0a01aae2a9ebdac3c2dd470e00f0e9037442","actual_client_binding_sha256":"265449eae162babf04f3415d8eb11a7bc3288ba3ef225940f423be7b4932d8a6"},"created_at":"2026-10-15T16:17:42.079422+00:00","created_by":"postgres","request_key":"55549f6a-b335-493d-850f-68bd9aac1b61","payload_sha256":"3948f9dca17362d2976f0486c58a5cc7588aa7da7a77d58950bd3bc418cab1f9","release_sha256":"614ef736c9a9042b0490fa096627ef5292e1241024713cb2a2bb091636fbb7a2","positive_staff_evidence_ref":"SOURCE_REVIEW_ONLY:/Users/antonello/Desktop/theuntoldstory/management/candidati/NARRATORE-UNIFICATO_2026-09-02/candidato/exam_human_master/HUMAN_OWNER_ACCEPTANCE_REVIEW.json","authorized_test_manifest_ref":"/Users/antonello/Desktop/theuntoldstory/management/candidati/NARRATORE-UNIFICATO_2026-09-02/candidato/exam_human_master/HUMAN_OWNER_ACCEPTANCE_MANIFEST.json"}]}$rootjson$::jsonb THEN RAISE EXCEPTION 'HUMAN_CUSTOM_BA