pg_catalog.text,pg_catalog.uuid)","public.mission_factory_quest_human_regia_optin_v1(pg_catalog.uuid,pg_catalog.int8,pg_catalog.text,pg_catalog.uuid)","public.mission_factory_quest_human_route_v1(pg_catalog.uuid)","public.mission_factory_quest_human_runtime_state_v1(pg_catalog.uuid)","public.mission_factory_quest_human_successor_scope_v1(pg_catalog.uuid)"]$human_signatures$::jsonb
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_owner_release_tuple#>'{db_core,functions}')x WHERE coalesce(x->>'oid','')!~'^[1-9][0-9]*$') THEN RETURN NULL;END IF;
 IF p_active THEN
