-- Included only in the reviewed atomic Root installer after genuine authority and full baseline CAS.
-- No standalone permit/apply. Fixed one-case budget; no old session ID is enabled or reopened.
DO $custom_staff_lease$
DECLARE v_kind jsonb;v_runtime jsonb;v_permit jsonb:=nullif(current_setting('tus.human_custom_install',true),'')::jsonb;v_count integer;
BEGIN
 IF current_user IS DISTINCT FROM 'postgres'::name OR auth.uid() IS NOT NULL OR v_permit IS NULL
 OR v_permit->>'expires_at' IS NULL OR (v_permit->>'expires_at')::timestamptz<=clock_timestamp()
 OR (v_permit->>'expires_at')::timestamptz>clock_timestamp()+interval '10 minutes'
 OR coalesce(v_permit->>'authority_sha256','')!~'^[0-9a-f]{64}$'
 OR jsonb_typeof(v_permit->'expected_kind') IS DISTINCT FROM 'object' OR jsonb_typeof(v_permit->'expected_runtime') IS DISTINCT FROM 'object'
 OR clock_timestamp()>='2026-10-16T08:10:00+00:00'::timestamptz THEN RAISE EXCEPTION 'HUMAN_CUSTOM_FINITE_STAFF_LEASE_AUTHORITY_REQUIRED';END IF;
 SELECT to_jsonb(ck) INTO v_kind FROM mission_factory_owner.c416_kind_admission ck WHERE singleton FOR UPDATE;
 SELECT to_jsonb(cr) INTO v_runtime FROM mission_factory_owner.c444_runtime_control cr WHERE singleton FOR UPDATE;
 IF v_kind IS DISTINCT FROM v_permit->'expected_kind' OR v_runtime IS DISTINCT FROM v_permit->'expected_runtime'
 OR (v_kind->>'enabled')::boolean IS DISTINCT FROM true OR (v_runtime->>'enabled')::boolean IS DISTINCT FROM true
 OR v_kind->'allowed_auth_ids' IS DISTINCT FROM '["f0856d53-83a6-4de0-bc0c-12c87916e665","b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b"]'::jsonb
 THEN RAISE EXCEPTION 'HUMAN_CUSTOM_STAFF_LEASE_FULL_BASELINE_DRIFT';END IF;
 UPDATE mission_factory_owner.c416_kind_admission SET bound_at='2026-10-16T06:10:00+00:00',expires_at='2026-10-16T08:10:00+00:00' WHERE singleton;
 GET DIAGNOSTICS v_count=ROW_COUNT;IF v_count<>1 THEN RAISE EXCEPTION 'HUMAN_CUSTOM_KIND_LEASE_COUNT';END IF;
 UPDATE mission_factory_owner.c444_runtime_control SET bound_at='2026-10-16T06:10:00+00:00',expires_at='2026-10-16T08:10:00+00:00' WHERE singleton;
 GET DIAGNOSTICS v_count=ROW_COUNT;IF v_count<>1 THEN RAISE EXCEPTION 'HUMAN_CUSTOM_RUNTIME_LEASE_COUNT';END IF;
 IF (SELECT to_jsonb(ck) FROM mission_factory_owner.c416_kind_admission ck WHERE singleton) IS DISTINCT FROM jsonb_set(jsonb_set(v_kind,'{bound_at}','"2026-10-16T06:10:00+00:00"'),'{expires_at}','"2026-10-16T08:10:00+00:00"')
 OR (SELECT to_jsonb(cr) FROM mission_factory_owner.c444_runtime_control cr WHERE singleton) IS DISTINCT FROM jsonb_set(jsonb_set(v_runtime,'{bound_at}','"2026-10-16T06:10:00+00:00"'),'{expires_at}','"2026-10-16T08:10:00+00:00"') THEN RAISE EXCEPTION 'HUMAN_CUSTOM_STAFF_LEASE_POST_DRIFT';END IF;
END $custom_staff_lease$;

COMMIT;
